INSERT INTO "cases" VALUES('D01','durian','disease','Thán thư lá','lá','Vết nâu có thể bắt đầu ở mép hoặc chóp lá và lan rộng.','Vết bắt đầu ở mép, chóp hay giữa lá?','Chụp cả hai mặt lá và toàn cành. Ghi thời điểm thấy đốm đầu tiên.','Đốm lá, tổn thương do điều kiện canh tác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D02','durian','disease','Xì mủ thân','thân;cành;gốc','Vùng vỏ sẫm, ẩm, có thể rỉ dịch.','Dịch chảy từ vết nứt tự nhiên hay từ vết thương nhìn thấy được?','Chụp sát vùng rỉ dịch và toàn thân đến gốc. Ghi tình trạng nước đọng sau mưa.','Vết thương cơ học, côn trùng đục thân','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D03','durian','disease','Cháy lá chết ngọn','lá;đọt','Lá bị cháy và phần đọt có thể suy hoặc khô.','Vết cháy chỉ trên lá hay đọt non cũng khô?','Chụp đọt và lá từ phần còn xanh đến phần khô, kèm ảnh toàn cành.','Thán thư, tổn thương phi sinh học','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D04','durian','disease','Đốm rong','lá;cành','Đốm tròn màu cam gạch hơi nổi trên mặt lá.','Đốm có nổi lên trên bề mặt lá không?','Chụp nghiêng dưới ánh sáng tự nhiên và lấy thêm ảnh toàn lá.','Đốm lá phẳng, lớp bám bề mặt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D05','durian','disease','Thối quả','quả','Đốm sẫm trên vỏ có thể lan thành mảng nâu.','Đốm xuất hiện khi quả còn trên cây hay sau thu hoạch?','Chụp mặt có vết và phần cuống quả. Ghi nhận vết nứt hoặc lỗ nhìn thấy.','Vết va đập, sâu đục quả','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D06','durian','disease','Thối rễ','rễ;tán','Tán có thể vàng, thưa, cành non suy và rễ bị hư.','Hiện tượng xảy ra ở một cây hay thành cụm tại vùng trũng?','Chụp toàn tán và mặt đất quanh gốc. Nhờ cán bộ chuyên môn kiểm tra rễ nếu cây suy nhanh.','Úng nước, tổn thương rễ khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D07','durian','pest','Rầy nhảy','lá non;đọt','Đọt và lá non bị hại, lá có thể biến dạng hoặc khô.','Mặt dưới lá non có côn trùng nhỏ hay vết bất thường không?','Chụp đọt và mặt dưới vài lá non. Ghi số cây có dấu hiệu tương tự.','Nhện hại, tổn thương lá non khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D08','durian','pest','Rệp sáp hại quả','quả;cuống quả','Có cụm côn trùng phủ sáp trắng ở quả hoặc gần cuống.','Lớp trắng là từng cụm nhỏ hay mảng phủ đều?','Chụp cận cụm trắng và toàn quả, chú ý vị trí quanh cuống.','Lớp bám hoặc nấm bề mặt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D09','durian','pest','Nhện đỏ','lá','Lá mất màu xanh bóng, có thể ngả màu đồng hoặc xám.','Lá non hay lá già đổi màu trước?','Chụp cả hai mặt lá. Nếu có kính lúp, quan sát và ghi lại chấm nhỏ di động.','Rầy nhảy, bụi bám, thiếu nước','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D10','durian','pest','Xén tóc đục thân cành','thân;cành','Có lỗ trên thân hoặc cành, đôi khi thấy vật liệu vụn ở vùng bị hại.','Có lỗ đục hoặc mùn cạnh vết hư không?','Chụp lỗ và vùng xung quanh, ghi chiều cao vị trí trên thân.','Xì mủ thân, tổn thương cơ học','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C01','coffee','disease','Gỉ sắt lá','lá','Mặt dưới lá có thể thấy lớp bột cam vàng, mặt trên có đốm vàng tương ứng.','Mặt dưới có lớp bột màu cam ngay dưới vết vàng không?','Chụp hai mặt cùng một lá và vài lá lân cận.','Đốm mắt cua, vàng lá do nguyên nhân khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C02','coffee','disease','Nấm hồng','cành;thân','Cành có vùng đổi màu hồng và phần phía ngoài vết bệnh có thể khô.','Phần cành khô có đi kèm mảng hồng trên vỏ không?','Chụp vùng chuyển tiếp giữa cành xanh và cành khô, kể cả chỗ phân cành.','Mọt đục cành, khô cành do điều kiện canh tác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C03','coffee','disease','Vàng lá thối rễ','rễ;tán','Cây sinh trưởng kém, vàng lá, rễ có thể thối hoặc sưng.','Cây vàng rải rác hay tập trung theo cụm?','Chụp toàn cây và gốc. Nếu cần lấy mẫu rễ, liên hệ đơn vị chuyên môn để được hướng dẫn.','Thiếu nước, thiếu dinh dưỡng, rệp sáp rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C04','coffee','disease','Đốm mắt cua','lá;quả','Vết trên lá thường tròn, tâm sáng hơn và mép sẫm.','Đốm có tâm sáng và viền nâu không?','Chụp cận vài đốm và mặt dưới lá để kiểm tra thêm dấu hiệu khác.','Gỉ sắt lá, đốm lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C05','coffee','pest','Rệp sáp chùm quả','quả;cuống quả','Cụm rệp phủ sáp trắng có thể nằm sát cuống hoặc bên trong chùm quả.','Cụm trắng nằm ở cuống quả hay cả trên cành?','Chụp toàn chùm và chỗ tiếp giáp cuống với quả. Ghi nhận số chùm có cụm trắng.','Lớp bám bề mặt, rệp sáp vùng rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C06','coffee','pest','Rệp sáp vùng rễ','rễ;gốc','Có thể thấy cụm rệp ở cổ rễ hoặc rễ, kèm cây suy.','Vùng cổ rễ đã lộ có cụm trắng hay nhiều kiến không?','Chụp phần cổ rễ nhìn thấy và toàn tán. Nhờ người có chuyên môn nếu cần kiểm tra dưới đất.','Vàng lá thối rễ, thiếu nước','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C07','coffee','pest','Mọt đục cành','cành','Cành bị héo hoặc khô, có thể thấy lỗ nhỏ tại đoạn bị hại.','Có lỗ nhỏ trên cành gần nơi phần ngọn bắt đầu héo không?','Chụp dọc cành và cận lỗ nếu thấy. Ghi số cành bị héo trên cây.','Nấm hồng, cành gãy hoặc tổn thương khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C08','coffee','pest','Mọt đục quả','quả','Có thể thấy lỗ đục nhỏ ở phía đầu quả.','Lỗ có nằm ở đầu quả và xuất hiện trên nhiều quả không?','Chụp đầu quả có lỗ, toàn chùm và vài quả liền kề. Ghi giai đoạn quả.','Tổn thương vỏ quả, đốm quả','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R01','rice','disease','Đạo ôn lá','lá','Vết điển hình có thể kéo dài, nhọn hai đầu, tâm nhạt hơn viền.','Vết có hình thoi hay tròn đều?','Chụp sát một vết rõ và toàn lá. Ghi giai đoạn lúa.','Đốm nâu, bạc lá','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R02','rice','disease','Đạo ôn cổ bông','cổ bông;bông','Vùng cổ bông có thể sẫm màu, phần bông phía trên có thể bạc hoặc hạt lép.','Cổ bông có vết sẫm ngay dưới bông không?','Chụp sát cổ bông, toàn bông và phần thân bên dưới.','Sâu đục thân, nguyên nhân gây lép khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R03','rice','disease','Khô vằn','bẹ lá','Vết trên bẹ có thể có tâm nhạt và viền nâu, thường cần kiểm tra các bẹ thấp.','Vết có xuất hiện trước ở bẹ gần mặt nước không?','Chụp bẹ dưới và vết cao nhất trên cùng một dảnh, kèm ảnh toàn bụi.','Tổn thương bẹ khác, bạc lá','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R04','rice','disease','Bạc lá vi khuẩn','lá','Vệt đổi màu có thể bắt đầu ở chóp hoặc mép lá và lan dọc phiến lá.','Vệt lan từ chóp hoặc mép, hay có đốm riêng ở giữa lá?','Chụp cả lá và mép vùng đang đổi màu. Ghi số bụi có triệu chứng.','Đạo ôn lá, cháy lá do điều kiện canh tác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R05','rice','disease','Đốm nâu','lá;hạt','Vết thường tròn hoặc bầu dục, có thể có tâm sáng hơn.','Đốm chủ yếu tròn hay thuôn nhọn ở hai đầu?','Chụp toàn lá và cận vài vết cạnh nhau. Ghi giai đoạn lúa.','Đạo ôn lá, các đốm lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R06','rice','pest','Rầy nâu','gốc;thân','Có thể quan sát rầy ở phần thấp của bụi lúa. Ruộng bị hại nặng có thể xuất hiện mảng khô nâu.','Có côn trùng nhỏ ở sát gốc và mảng khô tập trung không?','Chụp sát gốc của bụi ở rìa mảng bị hại và ghi nhận vị trí trên ruộng.','Khô hạn, ngộ độc hữu cơ, nhóm rầy khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R07','rice','pest','Sâu cuốn lá','lá','Lá gập hoặc cuốn, đôi khi thấy vệt trắng trên phần bị ăn.','Lá cuốn có vệt trắng hoặc thấy sâu trong nếp gấp không?','Chụp lá cuốn và toàn bụi. Ghi số lá có dấu hiệu trên vài bụi.','Lá cuộn do thiếu nước, sâu ăn lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R08','rice','pest','Sâu đục thân','thân;dảnh;bông','Dảnh giữa có thể héo khi cây còn non, hoặc xuất hiện bông bạc khi lúa trổ.','Có dảnh héo riêng lẻ hay bông bạc, và thân có dấu đục không?','Chụp cả bụi, thân và cổ bông. Ghi lúa đang đẻ nhánh hay đã trổ.','Đạo ôn cổ bông, nguyên nhân gây chết dảnh khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R09','rice','disease','Vàng lùn','lá;toàn cây','Bụi thấp, lá nhỏ có thể ngả xanh vàng, sinh trưởng khác bụi bên cạnh.','Bụi bị vàng có thấp hơn rõ so với bụi bên cạnh không?','Chụp cạnh nhau một bụi bị hại và một bụi bình thường. Ghi vị trí và liên hệ khuyến nông nếu lan thành cụm.','Lùn xoắn lá, thiếu dinh dưỡng, ngộ độc hữu cơ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R10','rice','disease','Lùn xoắn lá','lá;toàn cây','Cây thấp, sinh trưởng chậm, lá có thể xoắn.','Lá xoắn có đi cùng cây thấp và sinh trưởng chậm không?','Chụp toàn bụi, lá bị xoắn và bụi liền kề. Gửi cán bộ chuyên môn nếu nhiều bụi có dấu hiệu.','Vàng lùn, tổn thương lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R11','rice','abiotic','Nghi ngộ độc hữu cơ hoặc nghẹt rễ','rễ;toàn cây','Cây có thể vàng, chậm phát triển, rễ đổi màu ở ruộng có nhiều tàn dư hữu cơ.','Trước khi gieo cấy, ruộng có vùi nhiều rơm rạ hoặc ngập lâu không?','Chụp cả bụi và rễ của mẫu đã lấy, kèm ảnh mặt ruộng. Ghi lịch làm đất và tình trạng nước.','Thiếu dinh dưỡng, bệnh rễ, vàng lùn','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D11','durian','pest','Sâu đục hoa và quả','hoa;quả','Có thể thấy lỗ đục và phân sâu quanh vị trí bị hại trên quả.','Quả có lỗ rõ và vụn bám quanh lỗ hay chỉ có mảng đổi màu?','Chụp lỗ, toàn quả và vị trí các quả áp sát nhau.','Thối quả, quả bị cọ xát','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D12','durian','pest','Rầy xanh hại lá non','lá non','Lá non bị chích hút có thể cháy và rụng. Cần kiểm tra mặt dưới lá.','Có côn trùng nhỏ ở mặt dưới các lá non đang bị cháy không?','Chụp hai mặt lá non, ưu tiên ảnh có côn trùng nếu thấy.','Rầy nhảy, cháy lá chết ngọn','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D13','durian','pest','Mọt đục thân cành','gốc;thân;cành chính','Nên kiểm tra vùng thân hoặc cành chính phía dưới tán đang suy yếu.','Có nhiều lỗ nhỏ ở gốc hoặc cành chính không?','Chụp cận lỗ với vật làm mốc kích thước. Ghi có rỉ dịch quanh vết hay không.','Xén tóc, xì mủ thân','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D14','durian','disease','Lớp bồ hóng trên gai quả','quả','Lớp đen ngoài gai có thể xuất hiện cùng cụm rệp sáp.','Có thấy cụm trắng quanh cuống hoặc sát phần gai phủ đen không?','Chụp lớp đen và vùng quanh cuống. Ghi vỏ có lõm hoặc mềm không.','Thối quả, vết bẩn bề mặt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D15','durian','abiotic','Nghi thiếu nước kéo dài','lá;tán','Tán có thể héo lúc ban ngày, lá xỉn và mép lá vàng hoặc cháy.','Hiện tượng có rõ hơn giữa trưa sau nhiều ngày khô không?','Chụp tán buổi sáng và lúc héo. Ghi lịch tưới và xem đất quanh gốc có khô không.','Thối rễ, tổn thương do mặn','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D16','durian','abiotic','Nghi ảnh hưởng nước mặn','lá;tán','Tán suy hoặc cháy lá sau đợt nước tưới nghi nhiễm mặn cần được kiểm tra cùng lịch tưới.','Có đổi nguồn nước hoặc có thông báo xâm nhập mặn gần thời điểm xuất hiện dấu hiệu không?','Ghi nguồn nước và ngày tưới. Nếu đã đo độ mặn, gửi kèm kết quả và ảnh tán.','Thiếu nước, tổn thương rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D17','durian','abiotic','Sượng cơm','múi quả','Một phần thịt quả cứng hoặc chín không đều khi bổ.','Múi cứng đều hay chỉ cứng ở một vùng hoặc một số hộc?','Chụp mặt cắt vài múi của quả đã bổ. Ghi giống và thời điểm thu hoạch.','Cháy múi, thu hoạch chưa đủ độ già','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D18','durian','abiotic','Cháy múi','múi quả','Phần thịt quả có vùng thâm nâu có thể chỉ thấy sau khi bổ.','Vùng nâu ở đầu múi hay lan vào nhiều hộc? Vỏ quả bên ngoài có vết thối không?','Chụp mặt cắt, vỏ quả và cuống. Ghi giống, ngày thu hoạch và số quả bị tương tự.','Sượng cơm, thối quả','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D19','durian','disease','Đốm lá nghi Phomopsis','lá','Có thể có nhiều đốm nhỏ trên lá, kèm vùng lá cháy khi nặng.','Có các đốm tròn riêng trước khi lá cháy lan không?','Chụp lá ở các mức nhẹ và nặng, gồm cả mép lá và mặt dưới.','Thán thư, cháy lá chết ngọn','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C09','coffee','disease','Khô cành khô quả nghi thán thư','lá;cành;quả','Có thể thấy vết sẫm lõm trên cành và tổn thương sẫm trên quả.','Vùng khô có ranh giới rõ hoặc vết lõm trên cành mang quả không?','Chụp quả và đoạn cành ngay trước vị trí bắt đầu khô.','Nấm hồng, mọt đục cành, khô hạn','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C10','coffee','disease','Thối nứt thân','thân;gốc','Thân có vùng vỏ nứt hoặc thối. Mô tả mùi và diễn tiến giúp đánh giá thêm.','Vết nứt nằm ở gốc hay cao hơn? Có vùng vỏ mềm hoặc lỗ đục không?','Chụp toàn thân và vùng vỏ hư. Ghi vết lan theo chiều dọc hay quanh thân.','Sâu đục thân, vết thương cơ học','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C11','coffee','pest','Nghi tuyến trùng hại rễ','rễ;tán','Tán sinh trưởng chậm và rễ có thể sưng, đổi màu hoặc tổn thương.','Rễ có nốt sần hay chỉ bị đen hoặc thối?','Chụp bộ rễ đã lộ và toàn tán. Nhờ đơn vị chuyên môn hướng dẫn lấy mẫu.','Thối rễ do nấm, rệp sáp rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C12','coffee','pest','Nghi ấu trùng ve sầu hại rễ','rễ;tán','Cây có thể suy do ấu trùng gây hại rễ. Biểu hiện trên tán dễ trùng nguyên nhân khác.','Có thấy ấu trùng trong vùng đất quanh cây suy hoặc dấu hiệu tổn thương rễ không?','Chụp ấu trùng nếu đã thấy và toàn cây. Ghi vị trí các cây suy trong vườn.','Tuyến trùng, rệp sáp rễ, thiếu nước','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C13','coffee','pest','Bọ xít muỗi trên cà phê chè','đọt;lá non;quả','Vết chích sẫm màu ở phần non có thể cần kiểm tra côn trùng và loài cà phê.','Đây là cà phê chè hay cà phê vối? Vết tập trung trên đọt non hay quả?','Chụp đọt, quả và côn trùng nếu thấy. Ghi giống hoặc loại cà phê.','Đốm lá, tổn thương cơ học','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C14','coffee','abiotic','Nghi thiếu nước','lá;tán','Cây héo hoặc suy trong đợt khô kéo dài cần kiểm tra cùng tình trạng đất và lịch tưới.','Cây bắt đầu héo sau bao nhiêu ngày không mưa hoặc không tưới?','Chụp cây ở hai thời điểm trong ngày và ghi lịch tưới của từng khu.','Rễ bị hại, úng vùng rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C15','coffee','abiotic','Nghi úng vùng rễ','rễ;tán','Cây vàng ở khu trũng hoặc sau mưa kéo dài cần đối chiếu tình trạng nước đọng.','Nước còn đọng ở gốc và các cây thấp hơn bị nặng hơn không?','Chụp mặt đất quanh gốc, vị trí thoát nước và toàn tán.','Vàng lá thối rễ, thiếu dinh dưỡng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C16','coffee','abiotic','Nghi thiếu đạm ở cây giống','lá già;cây giống','Ở cây giống, lá già có thể nhạt màu tương đối đều và cây sinh trưởng yếu.','Lá già vàng trước hay lá mới vàng trước?','Chụp cả tầng lá già và đọt. Ghi tuổi cây và lịch dinh dưỡng.','Vấn đề rễ, các dạng thiếu dinh dưỡng khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C17','coffee','abiotic','Nghi thiếu magiê ở cây giống','lá già','Ở cây giống, vùng giữa gân lá già có thể vàng rõ hơn gân.','Vùng giữa gân vàng nhưng phần gân vẫn xanh không?','Chụp cận lá già và một lá non để đối chiếu. Ghi tuổi cây.','Thiếu đạm, vàng lá do vấn đề rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C18','coffee','abiotic','Nghi thiếu kali ở cây giống','lá già','Ở cây giống, mép lá già có thể đổi màu hoặc khô.','Mép lá già hay mép lá non đổi màu trước?','Chụp trọn lá già và toàn cây. Ghi lịch tưới để phân biệt với thiếu nước.','Khô hạn, tổn thương lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R12','rice','disease','Vàng giả hạt','bông;hạt','Một số hạt có thể biến thành khối màu vàng rồi sẫm hoặc ngả xanh.','Khối đổi màu thay thế riêng từng hạt hay cả bông đổi màu?','Chụp cận các hạt biến dạng và toàn bông.','Lem lép hạt, hạt đổi màu bề mặt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R13','rice','disease','Lúa von','toàn cây;thân','Một số cây có thể cao vống, nhạt màu so với các cây cùng tuổi.','Cây bất thường cao hơn hẳn các cây bên cạnh không?','Chụp cạnh nhau cây cao bất thường và cây bình thường. Ghi giống và ngày gieo.','Cây khác giống, chênh lệch sinh trưởng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R14','rice','disease','Đốm nâu hẹp','lá','Có thể thấy đốm nâu hẹp kéo dọc theo gân lá.','Vết là đường hẹp song song gân hay đốm tròn hoặc hình thoi?','Chụp lá dọc theo gân và lấy ảnh cận vài vết rõ.','Đốm nâu, đạo ôn lá','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R15','rice','disease','Thối bẹ lá đòng','bẹ lá;bông','Bẹ ôm đòng có thể bị thối và bông khó thoát ra.','Vết thối tập trung ở bẹ trên cùng quanh đòng hay ở bẹ dưới sát nước?','Chụp bẹ ôm đòng và bẹ thấp của cùng một dảnh.','Khô vằn, bông trổ không thoát do nguyên nhân khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R16','rice','disease','Đốm sọc vi khuẩn','lá','Có thể có vệt hẹp giữa các gân, lúc đầu nhìn hơi trong hoặc ướt.','Các vệt nằm giữa gân hay bắt đầu từ mép và chóp lá?','Chụp lá dưới ánh sáng tán xạ để thấy ranh giới giữa gân và vết.','Bạc lá vi khuẩn, đốm nâu hẹp','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R17','rice','pest','Ốc bươu vàng','mạ;gốc','Cây lúa non có thể bị cắn. Cần kiểm tra có ốc hoặc cụm trứng hồng gần mực nước không.','Có ốc hoặc ổ trứng hồng ở bờ và vùng mạ bị mất không?','Chụp vùng mạ bị hại, mực nước và ốc hoặc trứng nếu thấy.','Mạ chết do ngập, côn trùng cắn gốc','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R18','rice','pest','Bọ xít hôi hại lúa','bông;hạt','Bọ xít có thể thấy trên bông khi hạt đang phát triển. Hạt có thể lép hoặc đổi màu.','Lúa đang ngậm sữa và có thấy bọ xít thân dài trên bông không?','Chụp bông, côn trùng và ghi giai đoạn hạt ở vài điểm trên ruộng.','Lem lép hạt, bọ xít đen ở gốc','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R19','rice','pest','Bọ xít đen hại lúa','gốc;bẹ lá','Nên kiểm tra vùng gốc và bẹ thấp khi nghi có bọ xít đen.','Có côn trùng đen tụ ở sát gốc hoặc kẽ bẹ không?','Chụp cận côn trùng và vị trí của chúng trên bụi, kèm ảnh toàn ruộng.','Rầy nâu, côn trùng khác ở gốc','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R20','rice','pest','Sâu phao','lá;mặt nước','Có thể thấy mảnh lá cuộn thành ống và dấu ăn trên phiến lá.','Có ống bằng lá nổi gần chỗ các lá non bị ăn không?','Chụp mặt nước sát bụi lúa và phần phiến lá bị hại.','Sâu cuốn lá, sâu ăn lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R21','rice','abiotic','Nghi thiếu kẽm','lá;toàn cây','Lúa có thể còi từng mảng và lá xuất hiện đốm nâu nhỏ.','Dấu hiệu xuất hiện bao lâu sau cấy hoặc sạ? Có thành từng mảng không?','Chụp lá bị đốm, toàn bụi và vị trí các mảng. Ghi lịch nước.','Ngộ độc sắt, vàng lùn, các dạng thiếu dinh dưỡng khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R22','rice','abiotic','Nghi ngộ độc sắt','lá già;toàn cây','Lá thấp có thể xuất hiện đốm nâu nhỏ rồi chuyển màu đồng.','Đốm xuất hiện ở lá già hoặc các bụi ở chỗ trũng trước không?','Chụp lá già, lá non và khu vực ruộng. Ghi thời gian ngập và kết quả đo nếu có.','Thiếu kẽm, đốm nâu, ngộ độc hữu cơ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R23','rice','abiotic','Nghi tổn thương do mặn','lá;toàn cây','Chóp lá có thể trắng hoặc khô, đi cùng cây sinh trưởng kém khi có phơi nhiễm mặn.','Có đổi nguồn nước hoặc dấu hiệu xuất hiện sau đợt nước mặn vào ruộng không?','Chụp chóp lá và bản đồ vị trí ruộng. Ghi độ mặn nước nếu đã đo.','Thiếu dinh dưỡng, cháy lá do điều kiện khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R24','rice','disease','Lem lép hạt','hạt;bông','Vỏ hạt có thể bị lem sẫm màu và một số hạt bị teo hoặc lép. Dấu hiệu có thể do nhiều nguyên nhân.','Hạt bị lem trên vỏ hay chỉ lép? Có thấy thâm ở cổ bông hoặc vết trên bẹ lá cờ không?','Chụp toàn bông và một số hạt, thêm ảnh cổ bông và bẹ lá cờ. Ghi giai đoạn lúa và thời điểm bắt đầu thấy dấu hiệu.','Nhện gié, đạo ôn cổ bông, vàng giả hạt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R25','rice','pest','Nghi nhện gié','bẹ lá;bông;hạt','Có thể thấy vết đổi màu tím trên bẹ, kèm hạt lửng hoặc lép. Nhện rất nhỏ và khó thấy bằng mắt thường.','Bẹ lá cờ có vết đổi màu tím hay chỉ có hạt lem lép?','Chụp bẹ lá cờ và toàn bông. Nếu dấu hiệu xuất hiện trên nhiều bụi, gửi mẫu qua cán bộ chuyên môn để kiểm tra.','Lem lép hạt, thối bẹ lá đòng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C19','coffee','disease','Lở cổ rễ cây con','cổ rễ;gốc;thân;rễ','Vùng cổ rễ sát mặt giá thể có thể thối sẫm và teo lại. Cây con có thể chậm lớn, vàng lá và suy dần.','Phần thân sát mặt bầu có bị thắt lại đúng ở chỗ vết thâm không?','Chụp toàn cây và cổ rễ ngang mặt bầu, kèm ảnh cây khỏe ở bên cạnh.','Vàng lá thối rễ, úng bầu, tổn thương ở gốc','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C20','coffee','disease','Đốm lá nghi Corynespora','lá;gân lá;cuống lá;quả;cành','Trên cà phê vối Conilon ở Brazil, tài liệu ghi nhận đốm nâu có quầng vàng trên lá và có thể kèm rụng lá. Đốm sẫm trên quả có thể lan nhập lại.','Ngoài đốm có quầng vàng trên lá, cuống lá, gân lá hoặc quả có đốm tương tự không?','Chụp hai mặt lá và cả chùm quả nếu có đốm. Ghi loại cà phê đang trồng.','Đốm mắt cua, gỉ sắt, các dạng đốm lá khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C21','coffee','disease','Cháy lá dạng mạng tơ','lá;cành','Tài liệu Brazil mô tả sợi nấm trắng như mạng nhện phủ lá và cành. Lá có thể khô rồi vẫn treo trên cành nhờ các sợi này.','Có lá đã khô nhưng còn treo trên cành bởi những sợi trắng nối liền không?','Chụp chỗ sợi trắng nối lá với cành và ảnh toàn phần tán bị hại.','Mạng nhện thường, nấm hồng trên vỏ cành','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C22','coffee','disease','Đốm lá nghi Phoma','lá;cành;quả','Tài liệu Brazil ghi nhận mảng sẫm thường khởi đầu ở mép lá, đôi khi có các dải màu. Khi ẩm, có thể thấy chấm đen nhỏ trên vết bệnh.','Vết bắt đầu ở mép lá và có chấm đen li ti trên nền vết sẫm không?','Chụp rìa lá, bề mặt vết bệnh và cành có vết lõm nếu có.','Đốm lá vi khuẩn, thán thư, cháy mép lá do điều kiện canh tác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C23','coffee','disease','Đốm lá cây giống nghi Myrothecium','lá','Trên cây giống ở Brazil, đốm nâu tròn có rìa vàng ở hai mặt lá. Vết già có thể có tâm xám và cụm chấm đen đi kèm sợi trắng.','Trên cùng vết đốm, có thấy cụm chấm đen kèm sợi trắng ở hai mặt lá không?','Chụp cả hai mặt của lá cây giống và ghi tình trạng ẩm trong vườn ươm.','Đốm mắt cua, đốm lá nghi Phoma','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('C24','coffee','disease','Thối đen rễ nghi Rosellinia','rễ;cổ rễ;tán','Tài liệu Brazil ghi nhận cây vàng, héo và khô cành. Rễ gần cổ rễ có thể sẫm màu, với sợi trắng rồi sẫm dần ở mô bị hại.','Ở phần rễ đã lộ, có mảng sẫm kèm sợi bám hay chỉ thấy tán vàng?','Chụp toàn cây và rễ đã lộ. Nhờ cán bộ kỹ thuật kiểm tra mẫu để phân biệt với các nguyên nhân thối rễ khác.','Vàng lá thối rễ, tuyến trùng, úng nước','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D20','durian','disease','Nấm hồng trên cành','cành;thân','Tài liệu Malaysia và Indonesia mô tả lớp sợi trắng ban đầu trên vỏ cành, sau có thể thành mảng hồng nhạt. Vỏ có thể nứt và cành khô.','Ở ranh giới đoạn cành xanh và đoạn khô, vỏ có lớp hồng nhạt bám rõ không?','Chụp cả cành, mặt trên và mặt dưới chỗ có lớp hồng; ghi có lỗ đục ở gần không.','Xì mủ thân, cành bị mọt đục, tổn thương cơ học','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D21','durian','disease','Thối quả rụng nghi Sclerotium','quả','Tài liệu Malaysia mô tả quả rụng chạm đất có thể xuất hiện vết nâu ướt trên vỏ, phủ tơ nấm dày tỏa như hình quạt.','Quả đã chạm đất và lớp tơ trắng có tỏa từ vết nâu ướt không?','Chụp toàn quả, vị trí chạm đất và mép vùng bị thối.','Thối quả do Phytophthora, quả dập sau khi rụng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D22','durian','disease','Nấm rễ trắng nghi Rigidoporus','rễ;gốc;tán','Tài liệu Malaysia ghi nhận sợi nấm trắng phủ rễ, đôi lúc có thể thấy thể nấm ở gốc. Tán có thể vàng rồi khô và rụng lá.','Trên rễ đã lộ có dải sợi trắng bám dọc rễ hoặc thể nấm ở sát gốc không?','Chụp vùng gốc và rễ đã lộ, kèm ảnh toàn tán. Nhờ cán bộ kỹ thuật kiểm tra rễ.','Thối rễ, úng nước, rệp sáp ở rễ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('D23','durian','disease','Thối rễ nghi Phytopythium','rễ;tán;lá','Báo cáo tại Việt Nam ghi nhận thối rễ và rụng lá. Tài liệu Malaysia minh họa cây bị vàng lá và héo; những dấu hiệu trên tán có thể trùng với các dạng thối rễ khác.','Cây vàng, héo hoặc rụng lá có đi kèm rễ đã lộ bị thối không?','Chụp tán, gốc và rễ đã lộ. Ghi tình trạng đọng nước, rồi nhờ cán bộ kỹ thuật kiểm tra mẫu rễ để phân biệt tác nhân.','Thối rễ do Phytophthora, úng nước, nấm rễ trắng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R26','rice','disease','Cháy lá có vân sọc (leaf scald)','lá','Vết có thể bắt đầu ở chóp hoặc mép lá trưởng thành, với các dải nâu đậm và nhạt xen nhau. Khi các vết lan nhập, phần lá lớn có thể khô cháy.','Vết bắt đầu ở đầu hoặc mép lá và có các dải màu nâu xen nhau không?','Chụp trọn lá và vùng chuyển từ xanh sang cháy; chụp thêm lá lân cận.','Bạc lá vi khuẩn, đạo ôn lá, cháy chóp do điều kiện canh tác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R27','rice','disease','Thối thân lúa','bẹ lá;thân;gốc','Trong lúa gieo trên ruộng có nước, vết đen nhỏ có thể xuất hiện ở bẹ lá ngang mực nước. Về sau bẹ có thể chết và vết lan vào thân.','Vết đen bắt đầu ở bẹ thấp sát mực nước hay ở bẹ trên cùng quanh đòng?','Chụp bẹ sát mực nước và toàn dảnh lúa để thấy vị trí vết.','Khô vằn, đốm vòng bẹ lá, thối bẹ lá đòng','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R28','rice','disease','Đốm vòng trên bẹ lá lúa','bẹ lá;thân','Tài liệu UC IPM mô tả vết tròn hoặc bầu dục trên bẹ thấp, tâm xám xanh hoặc vàng rơm, viền nâu rõ. Một số vết có nhiều vòng đồng tâm.','Vết nằm trên bẹ thấp và có viền nâu thành vòng quanh tâm nhạt không?','Chụp sát viền vết, đồng thời chụp toàn dảnh để ghi vết đã lan lên cao đến đâu.','Khô vằn, thối thân lúa','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R29','rice','disease','Than đen hạt lúa','bông;hạt','Gần lúc chín, một vài hạt trên bông có thể phồng nhẹ hoặc nứt vỏ, lộ lớp bào tử đen thay một phần hoặc toàn bộ ruột hạt.','Màu đen lộ từ trong hạt nứt hay chỉ là vết lem ngoài vỏ?','Chụp cận hạt có vết nứt và toàn bông; ghi lúa đã gần thu hoạch chưa.','Vàng giả hạt, lem lép hạt','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R30','rice','disease','Thối hạt giống và mạ do nấm nước','hạt;mạ;gốc;rễ','Tài liệu UC IPM mô tả sợi trắng quanh vết nứt trên hạt hoặc gốc mạ mới mọc. Mạ sống sót có thể chậm lớn và vàng lá.','Mạ mới mọc có sợi trắng quanh hạt hoặc gốc và có mọc thưa thành vùng không?','Chụp hạt và gốc mạ, thêm ảnh vùng mạ mọc thưa. Ghi số ngày sau gieo.','Lúa von, ngộ độc hữu cơ, hạt không nảy mầm vì nguyên nhân khác','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R31','rice','disease','Nghi bệnh Tungro','lá;toàn cây','Tài liệu IRRI mô tả cây thấp và đẻ ít nhánh; lá có thể vàng đến vàng cam, đôi khi có đốm màu gỉ.','Bụi có lá vàng cam đồng thời thấp và ít nhánh rõ hơn bụi khỏe bên cạnh không?','Chụp cạnh nhau bụi bệnh và bụi khỏe, thêm ảnh phần lá vàng. Nhờ cán bộ kỹ thuật đánh giá nếu chỉ có dấu hiệu vàng và lùn.','Vàng lùn, thiếu dinh dưỡng, ngộ độc hữu cơ','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R32','rice','disease','Nghi tuyến trùng thân lúa (Ufra)','lá;bông;bẹ lá;thân','Tài liệu IRRI ghi nhận mô lá nhạt màu lúc đầu; cây có thể thấp, lá xoắn và bông trổ kẹt trong bẹ. Bông trổ ra có thể méo xoắn và hạt lép.','Ngoài lá bị xoắn, bông có trổ kẹt trong bẹ hoặc méo xoắn rõ không?','Chụp bẹ ôm bông, bông biến dạng và cả bụi; nhờ cán bộ kỹ thuật kiểm tra mẫu khi dấu hiệu trùng lùn xoắn lá.','Lùn xoắn lá, thối bẹ lá đòng, nhện gié','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
INSERT INTO "cases" VALUES('R33','rice','disease','Trắng chóp lá nghi tuyến trùng','lá;lá đòng;bông','Theo IRRI, đầu lá có thể mất màu rồi khô rách. Lá đòng đôi khi xoắn và bông trổ kém hoặc có nhiều hạt lép.','Chóp lá trắng có khô rách và đi kèm lá đòng bị xoắn không?','Chụp cận chóp lá, toàn lá đòng và bông nếu đã trổ; ghi giai đoạn sinh trưởng.','Tổn thương do mặn, cháy lá, lùn xoắn lá','approved','Chủ dự án AgriDoctor AI','2026-11-18','project');
