BEGIN TRANSACTION;
CREATE TABLE aliases(case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
  phrase TEXT NOT NULL, normalized TEXT NOT NULL, PRIMARY KEY(case_id,normalized));
CREATE TABLE case_scope(
    case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    dimension TEXT NOT NULL CHECK(dimension IN ('crop_type','growth_stage')),
    value TEXT NOT NULL CHECK(length(trim(value)) > 0),
    PRIMARY KEY(case_id,dimension)
);
CREATE TABLE case_sources(case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES sources(id), locator TEXT NOT NULL, PRIMARY KEY(case_id,source_id,locator));
CREATE TABLE cases(
  id TEXT PRIMARY KEY, crop_id TEXT NOT NULL REFERENCES crops(id),
  category TEXT NOT NULL CHECK(category IN ('disease','pest','abiotic')),
  title TEXT NOT NULL, organs TEXT NOT NULL, signs TEXT NOT NULL, follow_up TEXT NOT NULL,
  observation TEXT NOT NULL, lookalikes TEXT NOT NULL,
  review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','retired')),
  reviewed_by TEXT, reviewed_on TEXT, approval_scope text check(approval_scope in ('project','expert')),
  CHECK(review_status <> 'approved' OR (reviewed_by IS NOT NULL AND length(trim(reviewed_by))>0 AND reviewed_on IS NOT NULL AND date(reviewed_on) IS NOT NULL)),
  UNIQUE(crop_id,title)
);
CREATE TABLE crops(id TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL);
CREATE TABLE source_region(
    source_id TEXT PRIMARY KEY REFERENCES sources(id) ON DELETE CASCADE,
    region TEXT NOT NULL CHECK(length(trim(region)) > 0)
);
CREATE TABLE sources(id TEXT PRIMARY KEY, title TEXT NOT NULL, publisher TEXT NOT NULL, url TEXT NOT NULL UNIQUE);
CREATE INDEX cases_crop_status ON cases(crop_id,review_status);
CREATE VIEW case_catalog AS
SELECT c.*, p.name AS crop_name, s.id AS source_id, s.title AS source_title, s.publisher, s.url, cs.locator
FROM cases c JOIN crops p ON c.crop_id=p.id JOIN case_sources cs ON cs.case_id=c.id JOIN sources s ON s.id=cs.source_id;
COMMIT;
